      return user;
    },
    removeUser(id) {
      users.delete(id);
    },
    findInvitationByEmail(email) {
      return invitations.find((invitation) => invitation.email === email);
    },
    addInvitation(fields) {
      const invitation = { id: nextInvitationId++, ...fields, status: 'pending' };
      invitations.push(invitation);
      return invitation;
    },
  };
}
